    msg.extraText = gText;
    gpRecruitWindow->BroadcastMessage(&msg);

    msg.id = MESSAGE_WIDGET;
    msg.codeX = widget::WIDGET_SET_COLOR;
    msg.codeY = 0x21a;
    msg.extra = gUnnamed6aacb0->field_5a;
    gpRecruitWindow->BroadcastMessage(&msg);

